const staticData = $getWorkflowStaticData('global');

const categorias = [
  {
    id: 'cultura_general',
    nombre: 'Cultura General',
    instrucciones: 'Preguntas trampa que el 90% falla. Apela al ego: ¿Podrás responderla? Geografía, ciencia o récords.'
  },
  {
    id: 'cine_series',
    nombre: 'Cine y Series',
    instrucciones: 'Datos épicos de Marvel, Harry Potter, Star Wars o Animes famosos (Dragon Ball, One Piece).'
  },
  {
    id: 'futbol',
    nombre: 'Fútbol Mundial',
    instrucciones: 'Mundiales, Champions League, Messi, Cristiano Ronaldo, récords y finales históricas.'
  },
  {
    id: 'historia_misterio',
    nombre: 'Historia y Misterio',
    instrucciones: 'Curiosidades del Antiguo Egipto, Roma, misterios o civilizaciones perdidas.'
  },
  {
    id: 'ciencia_espacio',
    nombre: 'Ciencia y Espacio',
    instrucciones: 'Agujeros negros, el universo, fenómenos extremos o curiosidades del cuerpo humano.'
  }
];

if (typeof staticData.catIdx === 'undefined') {
  staticData.catIdx = 0;
}

const index = staticData.catIdx;
const actual = categorias[index];
staticData.catIdx = (index + 1) % categorias.length;

return {
  json: {
    category: actual.id,
    tema_nombre: actual.nombre,
    instrucciones: actual.instrucciones
  }
};

