const msg = $json.choices[0].message;
const raw = msg.content || msg.reasoning || '';
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  throw new Error('No se encontró JSON válido en Groq: ' + raw);
}

const data = JSON.parse(match[0]);
data.category = $('Rotar Categorias').item.json.category;
return { json: data };
